import { useLayoutEffect, useRef, type ReactNode } from 'react'

const STAR_COUNT = 42

type Star = {
  id: number
  left: number
  top: number
  size: number
  delay: number
  duration: number
  opacity: number
}

const unit = (seed: number) => {
  const value = Math.sin(seed * 997) * 10000
  return value - Math.floor(value)
}

type Spot = { left: number; top: number }
type Box = { left: number; top: number; right: number; bottom: number }

const CLEARANCE = 36

const CONTENT = [
  'header',
  'footer',
  'section[aria-label="Tecnologías que utilizo"]',
  'main h1',
  'main h2',
  'main h3',
  'main p',
  'main a',
  'main button',
  'main img',
  'main li',
  'main article',
].join(',')

const intersects = (a: Box, b: Box) =>
  a.left < b.right && a.right > b.left && a.top < b.bottom && a.bottom > b.top

const contentBoxes = (): Box[] =>
  [...document.querySelectorAll(CONTENT)].flatMap((node) => {
    const rect = node.getBoundingClientRect()
    if (rect.width < 2 || rect.height < 2) return []
    return [{
      left: rect.left - CLEARANCE,
      top: rect.top - CLEARANCE,
      right: rect.right + CLEARANCE,
      bottom: rect.bottom + CLEARANCE,
    }]
  })

const findSpot = (field: DOMRect, size: number, current: Spot): Spot | null => {
  const min = 12
  const maxLeft = field.width - size - min
  const maxTop = field.height - size - min
  if (maxLeft <= min || maxTop <= min) return null
  const boxes = contentBoxes()
  let nearby: Spot | null = null
  for (let attempt = 0; attempt < 40; attempt += 1) {
    const leftPx = min + Math.random() * (maxLeft - min)
    const topPx = min + Math.random() * (maxTop - min)
    const box = { left: leftPx, top: topPx, right: leftPx + size, bottom: topPx + size }
    if (boxes.some((obstacle) => intersects(box, obstacle))) continue
    const spot = { left: (leftPx / field.width) * 100, top: (topPx / field.height) * 100 }
    const dx = spot.left - current.left
    const dy = spot.top - current.top
    if (dx * dx + dy * dy > 18 * 18) return spot
    nearby = spot
  }
  return nearby
}

const guards = new Set<(boxes: Box[]) => void>()
let guardFrame = 0
let guardUsers = 0
let stopGuards = () => {}

const scheduleGuard = () => {
  if (guardFrame) return
  guardFrame = requestAnimationFrame(() => {
    guardFrame = 0
    const boxes = contentBoxes()
    guards.forEach((guard) => guard(boxes))
  })
}

const subscribeGuard = (guard: (boxes: Box[]) => void) => {
  guards.add(guard)
  if (guardUsers === 0) {
    window.addEventListener('scroll', scheduleGuard, { passive: true })
    window.addEventListener('resize', scheduleGuard)
    const main = document.getElementById('contenido')
    const observer = new MutationObserver(scheduleGuard)
    if (main) observer.observe(main, { childList: true, subtree: true })
    stopGuards = () => {
      window.removeEventListener('scroll', scheduleGuard)
      window.removeEventListener('resize', scheduleGuard)
      observer.disconnect()
      if (guardFrame) cancelAnimationFrame(guardFrame)
      guardFrame = 0
    }
  }
  guardUsers += 1
  return () => {
    guards.delete(guard)
    guardUsers -= 1
    if (guardUsers === 0) stopGuards()
  }
}

const Wander = ({
  size,
  delay,
  className,
  children,
}: {
  size: number
  delay: number
  className: string
  children: ReactNode
}) => {
  const nodeRef = useRef<HTMLSpanElement>(null)
  const spotRef = useRef<Spot>({ left: -20, top: -20 })

  useLayoutEffect(() => {
    const node = nodeRef.current
    const field = node?.parentElement
    if (!node || !field) return

    const relocate = () => {
      const spot = findSpot(field.getBoundingClientRect(), size, spotRef.current)
      if (!spot) {
        node.style.visibility = 'hidden'
        return
      }
      spotRef.current = spot
      node.style.visibility = ''
      node.style.left = `${spot.left}%`
      node.style.top = `${spot.top}%`
    }

    const guard = (boxes: Box[]) => {
      const bounds = field.getBoundingClientRect()
      const left = (spotRef.current.left / 100) * bounds.width
      const top = (spotRef.current.top / 100) * bounds.height
      const box = { left, top, right: left + size, bottom: top + size }
      if (boxes.some((obstacle) => intersects(box, obstacle))) node.style.visibility = 'hidden'
    }

    relocate()
    node.addEventListener('animationiteration', relocate)
    const unsubscribe = subscribeGuard(guard)
    return () => {
      node.removeEventListener('animationiteration', relocate)
      unsubscribe()
    }
  }, [size])

  return (
    <span
      ref={nodeRef}
      className={className}
      style={{
        visibility: 'hidden',
        left: 0,
        top: 0,
        width: size,
        height: size,
        animationDelay: `${delay}s`,
      }}
    >
      {children}
    </span>
  )
}

const STARS: readonly Star[] = Array.from({ length: STAR_COUNT }, (_, index) => {
  const seed = index + 1
  const prominence = unit(seed * 3)
  return {
    id: index,
    left: unit(seed) * 100,
    top: unit(seed * 2) * 100,
    size: prominence > 0.82 ? 11 + unit(seed * 4) * 7 : 4 + unit(seed * 4) * 5,
    delay: unit(seed * 5) * 7,
    duration: 2.8 + unit(seed * 6) * 3.4,
    opacity: 0.45 + prominence * 0.55,
  }
})

