const StarField = () => (
  <div className="star-field" aria-hidden="true">
    {STARS.map((star) => (
      <span
        key={star.id}
        className="star-spark"
        style={{
          left: `${star.left}%`,
          top: `${star.top}%`,
          width: star.size,
          height: star.size,
          animationDelay: `${star.delay}s`,
          animationDuration: `${star.duration}s`,
          opacity: star.opacity,
        }}
      />
    ))}
    {CATS.map((cat) => (
      <Wander key={cat.id} size={cat.size} delay={cat.delay} className="cat-face">
        <CatFace />
      </Wander>
    ))}
    {LOGOS.map(({ id, Mark, size, delay }) => (
      <Wander key={id} size={size} delay={delay} className="cat-face logo-mark">
        <Mark />
      </Wander>
    ))}
  </div>
)

export default StarField
